command:
// ==========================================
// LUNAS WIRKUNG: KLEMMENDE TÜR (RONDRA)
//
// - kein Target erforderlich
// - Markierung wird auf Tür, Luke oder Deckel platziert
// - Dauer: QS × 5 Minuten
// - Öffnung lässt sich auch mit Gewalt nicht öffnen
// - Zerstörung der Öffnung bleibt möglich
// - nur Quelleffekt auf dem Wirkenden
// - Effektanlage über Block 6
// - Markierungs-Cleanup über Block 17
// - Wirkungsendekarte über Block 7
// - öffentliche Gabenkarte über Block 11
// ==========================================

(async function () {

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden ||
    !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
    !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.Zone?.InitHooks;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen || !DSK_FW?.Zone?.InitHooks
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Klemmende Tür", vollerName = "Klemmende Tür (Rondra)", ahne = "Rondra";
const endeKey = "rondraKlemmendeTuer";
const endeText = "Die Verklemmung der Tür, Luke oder des Deckels löst sich auf. Die Öffnung lässt sich nun wieder normal öffnen.";

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

const safeTestData = typeof testData !== "undefined" ? testData : null;
const safeActor = typeof actor !== "undefined" ? actor : null;

let casterActor =
    safeTestData?.actor ||
    (safeTestData?.speaker?.token ? canvas.tokens.get(safeTestData.speaker.token)?.actor : null) ||
    safeActor ||
    canvas.tokens.controlled[0]?.actor ||
    game.user.character ||
    null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
        null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
}

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Kein Token des Wirkenden gefunden!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Klemmende Tür Probe", "Klemmende Tür"],
    testDataObj: safeTestData, fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Rondras Kraft konnte die Öffnung nicht verklemmen.",
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "0 Minuten", gmBereich: false,
        angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) await casterActor.unsetFlag("world", "letzteGabenQS");
    if (casterActor.getFlag("world", "letzteGabenMessageId") !== undefined) await casterActor.unsetFlag("world", "letzteGabenMessageId");
    return;
}

// +++ 4 - MARKIERUNG ERSTELLEN ++++++++++++++++++++++++++++++++

const bestaetigePosition = () => foundry.applications.api.DialogV2.wait({
    window: { title: "Tür markieren" },
    position: { width: 420 },
    content: `<form><div style="font-family:'Signika',sans-serif;">
        ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
        <div class="dskbox2" style="margin-top:10px;">
            <p style="font-size:.95em;line-height:1.35;">
                Verschiebe die Markierung passgenau auf die Tür, Luke oder den Deckel.
                <br><br>Klicke danach auf <b>Position bestätigen</b>.
            </p>
        </div>
    </div></form>`,
    buttons: [
        { action: "ok", label: "Position bestätigen", icon: "fas fa-check", default: true, callback: () => true },
        { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => false }
    ],
    rejectClose: false
});

ui.notifications.info("Luna sagt 🌙: Platziere die Markierung auf der Tür.");

const [templateDoc] = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [{
    t: "rect", user: game.user.id, distance: 0.7, direction: 45,
    x: casterToken.center.x, y: casterToken.center.y,
    fillColor: "#76301b", fillAlpha: 0.5, lineThickness: 2, hidden: false,
    flags: { dsk: { isZoneSource: true, gabenName: vollerName, casterUuid: casterActor.uuid } }
}]);

if (!templateDoc) return ui.notifications.error("Luna sagt 🌙: Die Markierung konnte nicht erstellt werden!");

try { canvas.templates.activate(); } catch {}
const bestaetigt = await bestaetigePosition();
try { canvas.tokens.activate(); } catch {}

if (!bestaetigt) {
    await templateDoc.delete();
    if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) await casterActor.unsetFlag("world", "letzteGabenQS");
    if (casterActor.getFlag("world", "letzteGabenMessageId") !== undefined) await casterActor.unsetFlag("world", "letzteGabenMessageId");
    return ui.notifications.warn("Luna sagt 🌙: Markierung abgebrochen.");
}

const template = canvas.scene.templates.get(templateDoc.id);
if (!template) return ui.notifications.error("Luna sagt 🌙: Die bestätigte Markierung wurde nicht gefunden!");

// +++ 5 - ALTEN EFFEKT ENTFERNEN ++++++++++++++++++++++++++++++

const alteEffekte = casterActor.effects.filter(effect =>
    (effect.name || effect.label || "") === vollerName &&
    (!effect.getFlag("dsk", "casterUuid") ||
        effect.getFlag("dsk", "casterUuid") === casterActor.uuid)
);

if (alteEffekte.length) {
    await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(effect => effect.id));
}

// +++ 6 - QUELLEFFEKT ÜBER BLOCK 6 ++++++++++++++++++++++++++++

const dauerMinuten = qs * 5;
const beschreibung =
    `<b>${casterName}</b> verklemmt eine Tür, Luke oder einen Deckel mit eiserner göttlicher Kraft.` +
    `<br><br>Die blockierte Öffnung lässt sich während der Wirkungsdauer <b>auch mit Gewalt nicht öffnen</b>.` +
    `<br>Die Tür, Luke oder der Deckel kann jedoch weiterhin <b>zerstört</b> werden, um einen Durchgang zu schaffen.`;

const effekt = await DSK_FW.Effekt.Anwenden({
    name: vollerName, ahne, beschreibung,
    gabeZiel: "", qs, ziel: casterActor,
    duration: { seconds: dauerMinuten * 60, startTime: game.time.worldTime },
    showIcon: 1,
    flags: { dsk: {
        isZoneSource: true, casterUuid: casterActor.uuid,
        templateId: template.id, templateUuid: template.uuid,
        casterEffektName: vollerName, radarTitel: gabenName, ahne, qs,
        wirkungsendeUeberBlock6: true,
        wirkungsende: {
            sfName: endeKey, basisEffektName: vollerName,
            beschreibungFuerEnde: endeText
        }
    }}
});

// +++ 7 - EFFEKT PRÜFEN + ROLLBACK ++++++++++++++++++++++++++++

const endeDaten = effekt?.getFlag("dsk", "wirkungsende");
const erfolgreich = Boolean(
    effekt &&
    (effekt.name || effekt.label || "") === vollerName &&
    effekt.getFlag("dsk", "isZoneSource") === true &&
    effekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
    effekt.getFlag("dsk", "templateId") === template.id &&
    effekt.getFlag("dsk", "templateUuid") === template.uuid &&
    effekt.getFlag("dsk", "wirkungsendeUeberBlock6") === true &&
    endeDaten?.sfName === endeKey &&
    endeDaten?.basisEffektName === vollerName &&
    endeDaten?.beschreibungFuerEnde === endeText
);

if (!erfolgreich) {
    if (effekt) try { await effekt.delete(); } catch {}
    if (canvas.scene.templates.get(template.id)) {
        await canvas.scene.deleteEmbeddedDocuments("MeasuredTemplate", [template.id]);
    }

    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung,
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: `${dauerMinuten} Minuten`,
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    return ui.notifications.error("Luna sagt 🌙: Klemmende Tür konnte nicht vollständig angewendet werden!");
}

// +++ 8 - ÖFFENTLICHE GABENKARTE ++++++++++++++++++++++++++++++

await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung,
    wirkender: casterName,
    ziele: [{ name: "Markierte Tür, Luke oder Deckel", rolle: "Blockierte Öffnung" }],
    misserfolge: [], dauerText: `${dauerMinuten} Minuten`,
    gmBereich: false, angewendet: true, erfolgreich: true,
    anfragenderUserId: game.user.id
});

// +++ 9 - QS-FLAGS AUFRÄUMEN ++++++++++++++++++++++++++++++++++

if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) await casterActor.unsetFlag("world", "letzteGabenQS");
if (casterActor.getFlag("world", "letzteGabenMessageId") !== undefined) await casterActor.unsetFlag("world", "letzteGabenMessageId");

ui.notifications.info(`Luna sagt 🌙: Die Öffnung ist für ${dauerMinuten} Minuten verklemmt.`);

}).call(this);
